def rascunho_sem_numero(apps, schema_editor):
    """Rascunho que nunca foi emitido perde o número: ele sai na primeira emissão (A13, D36)."""
    Proposta = apps.get_model("propostas", "Proposta")
    for proposta in Proposta.objects.filter(status="rascunho", versao=1):
        if not Proposta.objects.filter(numero=proposta.numero).exclude(pk=proposta.pk).exists():
            proposta.numero = None
            proposta.save(update_fields=["numero"])


def numerar_de_novo(apps, schema_editor):
    Proposta = apps.get_model("propostas", "Proposta")
    for proposta in Proposta.objects.filter(numero__isnull=True):
        proposta.numero = f"RASCUNHO-{proposta.pk}"
        proposta.save(update_fields=["numero"])


